# 43_ministerial_departures_reshuffle_split.R
# Ministers who left government entirely, split into reshuffle-coincident vs
# standalone departures, 1979-2025.
#
# Analytical purpose (Ch3 - The Political Class):
#   PJ, 8 Sep: "I think increase resignations exp for personal reason and/or
#   calls for resignation is an interestin line - and we have min reg data set
#   too" -> "I think we can have a double headed figure of total resignation
#   and ones for personal resons to get a sense of the different trends" ->
#   "start on the reshuffle-date compilation now - I think this is good reason
#   to keep the two lines so we can observe both."
#
#   IfG's own published chart ("Ministerial resignations outside reshuffles by
#   PM, 1979 to June 2023") is exactly this construct, but the page is blocked
#   to automated fetch for both PJ and Claude (same Cloudflare-style wall as
#   Parliament.uk before it) and no underlying data table was recoverable from
#   IfG's PDF reports either. Rather than wait on it, this reconstructs the
#   same distinction directly from the IfG Ministers Database we already have
#   (data/raw/ifg_ministers/), which needs no external access at all.
#
# METHOD - fully scripted, no hand-coding (matches the project's standing
#   preference for machine-derived over manually-coded classification, e.g.
#   64i_overlap_check_multiday.R in this same chapter):
#   1. A person's appointment ending is a LATERAL MOVE, not a departure from
#      government, if that same person has another appointment starting on
#      the SAME DAY or within the following 14 days (reshuffle promotions/
#      demotions/sideways moves). ⚠ BUG CAUGHT during build: a strict
#      start_date > end_date test misses the very common case of a same-day
#      post-to-post move (old post ends and new post starts on the identical
#      date) - checked directly, 2,073 of ~3,500 appointment-endings are
#      same-day moves for the same person. Must be start_date >= end_date.
#   2. Among genuine departures (no reappointment within 14 days), a
#      departure is GOVERNMENT-ENDED (mechanical, not personal) if it falls
#      within 3 days of the TRUE handover date for a general election or PM
#      change. ⚠ SECOND BUG CAUGHT during build: event.csv's own event dates
#      are NOT reliable handover dates - "formation complete" is dated when
#      the NEW team finished being appointed, which can be days (2010
#      coalition) to weeks (Johnson 2019, logged 9 Aug but the actual
#      May-to-Johnson handover and mass outgoing-minister exit was 24 Jul,
#      16 days earlier) away from when the OLD government's ministers
#      actually left. A naive +-3 day window around event.csv's own dates
#      wrongly classified the two largest reshuffle-scale clusters in the
#      whole dataset (2010-05-11, n=159; 2019-07-24, n=85) as "personal"
#      departures while government continued, massively inflating exactly
#      the years this series is meant to describe honestly. Fixed: for each
#      event.csv date, search +-30 days for the actual date with the most
#      same-day appointment-endings (the real handover day, cross-checked:
#      1997/2001/2005/2007/2010/2015/2016/2019/2022/2024 all land on dates
#      that independently make sense against the known history), then use
#      +-3 days around THAT corrected date.
#   ⚠ THIRD PASS, same bug family: a single-peak +-30 day search around each
#      event still missed 2022's DOUBLE transition (Johnson->Truss 6 Sep,
#      Truss->Sunak 25 Oct, seven weeks apart with follow-up reshuffle waves
#      in between) - "Truss government formation complete" is logged in
#      event.csv as 9 Oct, 33 days after her actual 6 Sep accession, outside
#      even a +-30 day window. Final method: for each election/PM-change
#      event, flag EVERY date within +-45 days where same-day endings hit an
#      unambiguous handover scale (>=20 - well above ordinary reshuffle-
#      cluster range) as government-ended, not just the single biggest day.
#      Checked this doesn't over-catch: the largest non-election reshuffle
#      in the whole 47-year dataset (2012-09-04, n=75, a genuine Cameron
#      reshuffle with NO PM change) sits nowhere near any election/PM-change
#      event date, so it correctly stays classified as a reshuffle-cluster,
#      not government-ended.
#   3. Among the remainder (left government, their own government did NOT
#      end that day), a departure is a RESHUFFLE-CLUSTER departure if 5 or
#      more OTHER appointments end on the same calendar date (a coordinated,
#      administratively-timed reshuffle move even without a PM change) -
#      threshold chosen empirically: the day-count distribution has a long
#      smooth decay from 1-10 then jumps into single-event outliers at
#      11-159 that all match known reshuffles/formations when cross-checked
#      against event.csv (see console output). ⚠ THIS THRESHOLD IS A REAL
#      JUDGEMENT CALL, flagged to PJ, not silently baked in - robustness at
#      3/5/10 reported in console output, all three saved as separate
#      columns so the headline choice is never hidden.
#   4. Everything left over is STANDALONE: a lone departure, on a day with no
#      unusual clustering, government continuing - the closest proxy
#      available from this data alone to "the interesting line" PJ named
#      (resignation for cause, disagreement, or health, not administrative
#      reshuffling). This is NOT yet cause-coded (scandal vs personal vs
#      policy) - that layer needs the Dowding/Berlinski lineage (Dowding &
#      Kang 1998, "Ministerial Resignations 1945-97", Public Administration
#      76:411-429; Berlinski, Dewan & Dowding 2012 book to 2007) once
#      accessible, or manual work to extend past 2007. Read STANDALONE as
#      "individual, non-reshuffle departure" - a real, useful, but broader
#      construct than "resigned for personal reasons" specifically.
#
# TWO LINES, as PJ asked to keep: TOTAL (left government, govt continued =
#   reshuffle-cluster + standalone) vs STANDALONE (the narrower subset).
#
# ⚠⚠ CIRCULARITY CHECK, 8 Sep — PJ flagged, then refined: "personal resignations
#   not so this is a plausible DV". Ch2's exec_instab (turbulence-composite
#   component) is built from THIS SAME data/raw/ifg_ministers/appointment.csv
#   (WKBD_repo/scripts/03_cabinet_turnover.R, RAW full-cabinet appointment-
#   endings, unfiltered for lateral moves). Checked the actual overlap
#   directly rather than assuming: of the 629 raw cabinet-rank endings that
#   feed exec_instab, only 59 (9.4%) would qualify as STANDALONE here — the
#   other 90.6% is exactly the lateral-move/government-ended churn this
#   script filters out. So:
#   - STANDALONE is a genuinely distinct construct from exec_instab (mostly
#     routine reshuffle churn), so it WOULD be defensible as its own DV in
#     principle - checked and confirmed, not just asserted.
#   - ✅ DECIDED, 8 Sep, PJ: "agree - not using this for the statistical
#     analysis, we have professionalism for that." Both TOTAL and STANDALONE
#     stay DESCRIPTIVE ONLY - part of Ch3's "building the case" narrative
#     (like Figure 3.4), never regressed against anything. The existing
#     professionalisation index (41e_professionalisation_pca.R) remains the
#     one IV doing statistical work in this chapter. No modelling role for
#     this series is planned.
#
# DATA SOURCE: data/raw/ifg_ministers/{appointment,event}.csv (IfG Ministers
#   Database, CC-BY-4.0, since 1979).
#
# OUTPUT: data/processed/ministerial_departures_annual_1979_2025.csv
#         (diagnostic console output only - no figure yet, PJ to review the
#          series and the reshuffle-threshold choice before a figure is built)

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr, tidyr)

PROJECT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  root <- if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "..")) else getwd()
  root
})
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
IFG_DIR   <- file.path(WKBD_ROOT, "data/raw/ifg_ministers")
DATA_OUT <- file.path(PROJECT, "data/processed/ministerial_departures_annual_1979_2025.csv")

app <- read_csv(file.path(IFG_DIR, "appointment.csv"), show_col_types = FALSE)
ev  <- read_csv(file.path(IFG_DIR, "event.csv"), show_col_types = FALSE)

daily_all <- app |> filter(!is.na(end_date)) |> count(end_date, name = "n_ending_that_day")

# TRUE handover dates: for each logged election/PM-change event, flag EVERY
# date within +-45 days at unambiguous handover scale (>=20 same-day
# endings), not just the single biggest day - see header comment for why
# (2022's double PM change needed this, a single-peak search missed it).
gov_events <- ev |> filter(type %in% c("General election", "Change of prime minister")) |> pull(date)
find_handover_dates <- function(e) {
  w <- daily_all |> filter(end_date >= e - 45, end_date <= e + 45, n_ending_that_day >= 20)
  w$end_date
}
gov_end_dates <- as.Date(sort(unique(do.call(c, lapply(gov_events, find_handover_dates)))), origin = "1970-01-01")
cat("Corrected government-handover dates used for the gov_ended filter:\n")
print(gov_end_dates)

departures <- app |> filter(!is.na(end_date))
cat(sprintf("Total appointment-endings, all dates: %d\n", nrow(departures)))

# 1. LATERAL MOVE CHECK: same person, new appointment starting within 14 days
starts <- app |> select(person_id, start_date)
departures <- departures |>
  rowwise() |>
  mutate(moved_within_14d = any(starts$person_id == person_id &
                                   starts$start_date >= end_date &
                                   starts$start_date <= end_date + 14)) |>
  ungroup()

left_govt <- departures |> filter(!moved_within_14d)
cat(sprintf("Lateral moves (excluded): %d\n", sum(departures$moved_within_14d)))
cat(sprintf("Genuine departures from government: %d\n", nrow(left_govt)))

# 2. GOVERNMENT-ENDED CHECK: within 3 days of a general election / PM change
left_govt <- left_govt |>
  rowwise() |>
  mutate(gov_ended = any(abs(as.numeric(end_date - gov_end_dates)) <= 3)) |>
  ungroup()

personal_window <- left_govt |> filter(!gov_ended)
cat(sprintf("Government-ended departures (excluded, mechanical): %d\n", sum(left_govt$gov_ended)))
cat(sprintf("Departures while own government continued: %d\n", nrow(personal_window)))

# 3. RESHUFFLE-CLUSTER CHECK: robustness at 3 thresholds
daily_all <- app |> filter(!is.na(end_date)) |> count(end_date, name = "n_ending_that_day")
personal_window <- personal_window |> left_join(daily_all, by = "end_date")

for (thr in c(3, 5, 10)) {
  col <- paste0("standalone_thr", thr)
  personal_window[[col]] <- personal_window$n_ending_that_day < thr
}

cat("\n=== Robustness: standalone counts under 3 clustering thresholds ===\n")
for (thr in c(3, 5, 10)) {
  col <- paste0("standalone_thr", thr)
  cat(sprintf("Threshold >= %d other endings same day = reshuffle: %d standalone of %d\n",
              thr, sum(personal_window[[col]]), nrow(personal_window)))
}

# Headline threshold = 5 (documented above); other two kept as robustness columns.
personal_window$standalone <- personal_window$standalone_thr5

# ============================================================
# ANNUAL SERIES, 1979-2025
# ============================================================
personal_window <- personal_window |> mutate(year = as.integer(format(end_date, "%Y")))

annual <- personal_window |>
  filter(year >= 1979, year <= 2025) |>
  group_by(year) |>
  summarise(n_total_departures = n(),
            n_standalone_thr3  = sum(standalone_thr3),
            n_standalone_thr5  = sum(standalone_thr5),
            n_standalone_thr10 = sum(standalone_thr10),
            .groups = "drop") |>
  complete(year = 1979:2025, fill = list(n_total_departures = 0, n_standalone_thr3 = 0,
                                           n_standalone_thr5 = 0, n_standalone_thr10 = 0)) |>
  arrange(year)

# ============================================================
# DENOMINATOR — active ministers in post (1 July snapshot each year)
# ============================================================
# PJ, 8 Sep: "I guess the data are not striking in the sense that resignations
# increading anyway so part of that" - i.e. is the raw-count rise just tracking
# a bigger government? Checked directly: government headcount only grew ~33%
# (108 -> 144 active ministers, 1979-88 to 2020-25) while raw departures grew
# ~3x - so the RATE (per 100 ministers) is the honest way to show this is not
# a headcount artefact.
n_active <- sapply(annual$year, function(yr) {
  d <- as.Date(sprintf("%d-07-01", yr))
  app |> filter(start_date <= d, is.na(end_date) | end_date >= d) |> nrow()
})
annual$n_active_ministers <- n_active
annual$total_rate_pct      <- 100 * annual$n_total_departures / annual$n_active_ministers
annual$standalone_rate_pct <- 100 * annual$n_standalone_thr5  / annual$n_active_ministers

write_csv(annual, DATA_OUT)
cat(sprintf("\nSaved: %s\n", DATA_OUT))

cat("\n=== Period totals and rates (per 100 active ministers) ===\n")
period_tbl <- annual |>
  mutate(period = cut(year, breaks = c(1978, 1988, 1997, 2009, 2019, 2025),
                       labels = c("1979-88", "1989-97", "1998-2009", "2010-19", "2020-25"))) |>
  group_by(period) |>
  summarise(mean_active = mean(n_active_ministers),
            total = sum(n_total_departures), total_rate_pct = mean(total_rate_pct),
            standalone = sum(n_standalone_thr5), standalone_rate_pct = mean(standalone_rate_pct),
            .groups = "drop")
print(period_tbl)

cat(sprintf("\nTotal rate: %.1fx from 1979-88 to 2020-25 (%.1f%% -> %.1f%%)\n",
    period_tbl$total_rate_pct[5]/period_tbl$total_rate_pct[1],
    period_tbl$total_rate_pct[1], period_tbl$total_rate_pct[5]))
cat(sprintf("Standalone rate: %.1fx from 1979-88 to 2020-25 (%.1f%% -> %.1f%%)\n",
    period_tbl$standalone_rate_pct[5]/period_tbl$standalone_rate_pct[1],
    period_tbl$standalone_rate_pct[1], period_tbl$standalone_rate_pct[5]))

cat(sprintf("\n47-year totals: %d departures while government continued, %d standalone (thr5)\n",
            sum(annual$n_total_departures), sum(annual$n_standalone_thr5)))
